#include <bits/stdc++.h>
using namespace std;

struct Ori {
    vector<pair<int,int>> cells;
    int w, h, r, f;
};

vector<Ori> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Ori> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> tr;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) { int nx = ty, ny = -tx; tx = nx; ty = ny; }
                tr.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto& [a,b] : tr) { minx = min(minx,a); miny = min(miny,b); }
            for (auto& [a,b] : tr) { a -= minx; b -= miny; }
            sort(tr.begin(), tr.end());
            if (seen.insert(tr).second) {
                int mx=0, my=0;
                for (auto [a,b] : tr) { mx=max(mx,a); my=max(my,b); }
                res.push_back({tr, mx+1, my+1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin >> n;
    int totalCells = 0;
    vector<int> ks(n);
    vector<vector<pair<int,int>>> rawCells(n);
    for (int i = 0; i < n; i++) {
        cin >> ks[i]; rawCells[i].resize(ks[i]);
        for (int j = 0; j < ks[i]; j++) cin >> rawCells[i][j].first >> rawCells[i][j].second;
        totalCells += ks[i];
    }
    vector<vector<Ori>> allO(n);
    for (int i = 0; i < n; i++) allO[i] = getOrientations(rawCells[i]);
    vector<int> order(n); iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return ks[a] > ks[b]; });

    long long bestArea = LLONG_MAX;
    int bestW=0, bestH=0;
    vector<int> bX(n), bY(n), bR(n), bF(n);
    auto t0 = chrono::steady_clock::now();

    auto tryW = [&](int W) {
        vector<int> colH(W, 0);
        set<pair<int,int>> used;
        int curH = 0;
        vector<int> px(n), py(n), pr(n), pf(n);
        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];
            long long bs = LLONG_MAX; int bx=-1,by=-1,bo=-1;
            for (int oi = 0; oi < (int)allO[i].size(); oi++) {
                auto& o = allO[i][oi];
                if (o.w > W) continue;
                for (int x = 0; x <= W - o.w; x++) {
                    int y = 0;
                    for (auto [cx,cy] : o.cells) y = max(y, colH[x+cx] - cy);
                    if (y < 0) y = 0;
                    bool ok = true;
                    for (auto [cx,cy] : o.cells) if (used.count({x+cx, y+cy})) { ok=false; break; }
                    if (!ok) { for (int dy=y+1; dy<=y+50; dy++) { ok=true; for (auto [cx,cy]:o.cells) if(used.count({x+cx,dy+cy})){ok=false;break;} if(ok){y=dy;break;}} if(!ok) continue; }
                    long long mh = max(curH, y + o.h);
                    long long sc = mh * 1000000LL + y * 1000LL + x;
                    if (sc < bs) { bs=sc; bx=x; by=y; bo=oi; }
                }
            }
            if (bx < 0) return;
            auto& o = allO[i][bo];
            px[i]=bx; py[i]=by; pr[i]=o.r; pf[i]=o.f;
            for (auto [cx,cy]:o.cells) { used.insert({bx+cx,by+cy}); colH[bx+cx]=max(colH[bx+cx],by+cy+1); curH=max(curH,by+cy+1); }
        }
        long long area = (long long)W * curH;
        if (area < bestArea) { bestArea=area; bestW=W; bestH=curH; bX=px; bY=py; bR=pr; bF=pf; }
    };

    int sq = max(1, (int)ceil(sqrt((double)totalCells)));
    for (int w = max(1, sq/2); w <= sq*3 && w <= totalCells+10; w++) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now-t0).count() > 8500) break;
        tryW(w);
    }
    if (bestArea == LLONG_MAX) tryW(totalCells+10);

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) cout << bX[i] << " " << bY[i] << " " << bR[i] << " " << bF[i] << "\n";
}
